const __vite__css = "#root {
  width: 100%;
}

.page {
  width: min(1400px, calc(100% - 48px));
  margin: 0 auto;
  padding: 48px 0 80px;
}

.header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 32px;
  margin-bottom: 32px;
}

.eyebrow {
  margin: 0 0 8px;
  color: #7c8ba1;
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

h1 {
  margin: 0;
  font-size: clamp(2rem, 4vw, 3.3rem);
  line-height: 1;
}

.subtitle {
  margin: 14px 0 0;
  color: #8f9bad;
}

.supplier-count {
  min-width: 110px;
  padding: 18px 24px;
  border: 1px solid #2a3140;
  border-radius: 16px;
  background: #171a21;
  text-align: center;
}

.supplier-count strong {
  display: block;
  font-size: 1.8rem;
}

.supplier-count span {
  color: #8f9bad;
  font-size: 0.85rem;
}

.filters {
  display: flex;
  align-items: flex-end;
  gap: 16px;
  padding: 20px;
  margin-bottom: 24px;
  border: 1px solid #2a3140;
  border-radius: 16px;
  background: #171a21;
}

.filters label {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 8px;
  color: #9ca8ba;
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
}

select,
button {
  min-height: 44px;
  border-radius: 10px;
  font: inherit;
}

select {
  padding: 0 12px;
  border: 1px solid #343c4d;
  background: #101218;
  color: #f4f6fa;
}

.secondary-button {
  padding: 0 18px;
  border: 1px solid #343c4d;
  background: transparent;
  color: #d9dfeb;
  cursor: pointer;
}

.secondary-button:hover {
  background: #222733;
}

.table-card {
  overflow: hidden;
  border: 1px solid #2a3140;
  border-radius: 16px;
  background: #171a21;
}

.table-wrapper {
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
}

th {
  padding: 15px 18px;
  border-bottom: 1px solid #313746;
  background: #1c2029;
  color: #8592a6;
  font-size: 0.72rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

td {
  padding: 17px 18px;
  border-bottom: 1px solid #272d39;
  vertical-align: middle;
}

tbody tr:last-child td {
  border-bottom: 0;
}

tbody tr:hover {
  background: #1b1f28;
}

.secondary-text {
  display: block;
  margin-top: 5px;
  color: #778397;
  font-size: 0.78rem;
}

.category-list {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.category {
  padding: 5px 8px;
  border-radius: 7px;
  background: #242b37;
  color: #b4bfd0;
  font-size: 0.7rem;
}

.status {
  display: inline-block;
  padding: 5px 9px;
  border-radius: 999px;
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: capitalize;
}

.status.active {
  background: rgba(42, 180, 100, 0.14);
  color: #67db94;
}

.status.suspended {
  background: rgba(235, 91, 91, 0.14);
  color: #ff7b7b;
}

.incident-status-open {
  background: rgba(77, 115, 255, 0.14);
  color: #7a9bff;
}

.incident-status-in_progress {
  background: rgba(240, 180, 41, 0.14);
  color: #f0c94a;
}

.incident-status-resolved {
  background: rgba(42, 180, 100, 0.14);
  color: #67db94;
}

.incident-status-discarded {
  background: rgba(235, 91, 91, 0.14);
  color: #ff7b7b;
}

.state-card,
.empty-state {
  padding: 40px;
  border: 1px solid #2a3140;
  border-radius: 16px;
  background: #171a21;
  text-align: center;
}

.state-card.error {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

.error {
  color: #ff7b7b;
}

.field-error {
  margin-top: 6px;
  color: #ff7b7b;
  font-size: 0.78rem;
  font-weight: 600;
  text-transform: none;
}

.field-hint {
  color: #f0c94a;
  font-size: 0.78rem;
  font-weight: 600;
  text-transform: none;
}

.branch-highlight {
  padding: 10px;
  border: 1px solid #f0c94a;
  border-radius: 10px;
  background: rgba(240, 180, 41, 0.08);
}

.summary-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 20px;
}

.summary-card {
  padding: 20px 24px;
  border: 1px solid #2a3140;
  border-radius: 16px;
  background: #171a21;
}

.summary-card h2 {
  margin: 0 0 14px;
  font-size: 1.1rem;
}

.summary-card ul {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.summary-card li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 10px;
  border-bottom: 1px solid #272d39;
  color: #b4bfd0;
  font-size: 0.9rem;
}

.summary-card li:last-child {
  padding-bottom: 0;
  border-bottom: 0;
}

.summary-card li strong {
  color: #f4f6fa;
  font-size: 1rem;
}

@media (max-width: 900px) {
  .summary-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 760px) {
  .page {
    width: min(100% - 24px, 1400px);
    padding-top: 28px;
  }

  .header {
    align-items: stretch;
    flex-direction: column;
  }

  .supplier-count {
    align-self: flex-start;
  }

  .filters {
    align-items: stretch;
    flex-direction: column;
  }
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

.primary-button {
  padding: 0 18px;
  border: 1px solid #3559d8;
  background: #3559d8;
  color: white;
  cursor: pointer;
  font-weight: 700;
}

.primary-button:hover {
  background: #2d4cbd;
}

.primary-button:disabled,
.small-button:disabled,
.rate-editor button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.create-card {
  margin-bottom: 24px;
  padding: 24px;
  border: 1px solid #2a3140;
  border-radius: 16px;
  background: #171a21;
}

.form-heading {
  margin-bottom: 20px;
}

.form-heading h2 {
  margin: 0;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 20px;
}

.form-grid label {
  display: flex;
  flex-direction: column;
  gap: 8px;
  color: #9ca8ba;
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
}

input,
textarea {
  width: 100%;
  border: 1px solid #343c4d;
  border-radius: 10px;
  background: #101218;
  color: #f4f6fa;
  font: inherit;
}

input {
  min-height: 44px;
  padding: 0 12px;
}

textarea {
  min-height: 100px;
  padding: 12px;
  resize: vertical;
}

input[readonly] {
  color: #8f9bad;
  cursor: default;
}

.notes-field {
  grid-column: 1 / -1;
}

.action-message {
  margin-bottom: 20px;
  padding: 14px 18px;
  border-radius: 10px;
  font-weight: 600;
}

.success-message {
  border: 1px solid rgba(42, 180, 100, 0.35);
  background: rgba(42, 180, 100, 0.12);
  color: #67db94;
}

.error-message {
  border: 1px solid rgba(235, 91, 91, 0.35);
  background: rgba(235, 91, 91, 0.12);
  color: #ff7b7b;
}

.rate-editor {
  display: flex;
  align-items: center;
  gap: 8px;
}

.rate-editor input {
  width: 90px;
  min-height: 36px;
}

.rate-editor button,
.small-button {
  min-height: 36px;
  padding: 0 12px;
  border: 1px solid #343c4d;
  background: #222733;
  color: #d9dfeb;
  cursor: pointer;
}

.rate-editor button:hover,
.small-button:hover {
  background: #2d3442;
}

@media (max-width: 900px) {
  .form-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 760px) {
  .header-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .form-grid {
    grid-template-columns: 1fr;
  }

  .notes-field {
    grid-column: auto;
  }
}

/* ──────────────────────────────────────────────
   Inventory — Stock badges
   ────────────────────────────────────────────── */

.stock-healthy {
  background: rgba(42, 180, 100, 0.14);
  color: #67db94;
}

.stock-low {
  background: rgba(240, 180, 41, 0.14);
  color: #f0c94a;
}

.stock-out {
  background: rgba(235, 91, 91, 0.14);
  color: #ff7b7b;
}

.stock-display {
  display: flex;
  align-items: center;
  margin-top: 4px;
  padding: 10px 14px;
  border: 1px solid #2a3140;
  border-radius: 10px;
  background: #101218;
  color: #b4bfd0;
  font-size: 0.85rem;
  font-weight: 400;
  text-transform: none;
  min-height: 20px;
}

.stock-display.stock-out {
  border-color: rgba(235, 91, 91, 0.35);
  color: #ff7b7b;
}

.stock-display.stock-low {
  border-color: rgba(240, 180, 41, 0.35);
  color: #f0c94a;
}

.stock-display.stock-healthy {
  border-color: rgba(42, 180, 100, 0.35);
  color: #67db94;
}

/* ──────────────────────────────────────────────
   Inventory — Movement kind badges
   ────────────────────────────────────────────── */

.status-entry {
  background: rgba(42, 180, 100, 0.14);
  color: #67db94;
}

.status-exit {
  background: rgba(235, 91, 91, 0.14);
  color: #ff7b7b;
}

.row-entry td {
  border-left: 3px solid rgba(42, 180, 100, 0.35);
}

.row-exit td {
  border-left: 3px solid rgba(235, 91, 91, 0.35);
}

/* ──────────────────────────────────────────────
   Inventory — Field warning (exceeds stock)
   ────────────────────────────────────────────── */

.field-warning {
  margin-top: 6px;
  color: #f0c94a;
  font-size: 0.78rem;
  font-weight: 600;
  text-transform: none;
}

/* ──────────────────────────────────────────────
   Inventory — UUID cell (full uuid display)
   ────────────────────────────────────────────── */

.uuid-cell {
  font-family: 'SFMono-Regular', Consolas, 'Liberation Mono', Menlo, monospace;
  font-size: 0.72rem;
  color: #778397;
  white-space: nowrap;
  max-width: 180px;
  overflow-x: auto;
  scrollbar-width: thin;
}

/* ──────────────────────────────────────────────
   Auth pages — Login & Register
   ────────────────────────────────────────────── */

.auth-page {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  padding: 24px;
}

.auth-card {
  width: 100%;
  max-width: 440px;
  padding: 40px 32px;
  border: 1px solid #2a3140;
  border-radius: 20px;
  background: #171a21;
}

.auth-header {
  margin-bottom: 32px;
  text-align: center;
}

.auth-header h1 {
  margin: 0 0 8px;
}

.auth-card label {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 20px;
  color: #9ca8ba;
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
}

.auth-card input {
  width: 100%;
  min-height: 44px;
  padding: 0 12px;
  border: 1px solid #343c4d;
  border-radius: 10px;
  background: #101218;
  color: #f4f6fa;
  font: inherit;
}

.auth-card input::placeholder {
  color: #566073;
}

.auth-button {
  width: 100%;
  min-height: 48px;
  margin-top: 8px;
  font-size: 1rem;
}

.auth-error {
  margin-bottom: 16px;
  padding: 12px 14px;
  border: 1px solid rgba(235, 91, 91, 0.35);
  border-radius: 10px;
  background: rgba(235, 91, 91, 0.12);
  color: #ff7b7b;
  font-weight: 600;
  text-align: center;
}

.auth-alt {
  margin-top: 24px;
  color: #8f9bad;
  text-align: center;
  font-size: 0.9rem;
}

.auth-alt a {
  color: #4d73ff;
  text-decoration: none;
  font-weight: 600;
}

.auth-alt a:hover {
  text-decoration: underline;
}

.auth-forgot-link {
  display: block;
  margin-top: 4px;
  color: #4d73ff;
  font-size: 0.8rem;
  font-weight: 600;
  text-decoration: none;
  text-transform: none;
}

.auth-forgot-link:hover {
  text-decoration: underline;
}

/* ──────────────────────────────────────────────
   Navigation link (suppliers-to-profile)
   ────────────────────────────────────────────── */

.nav-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  text-decoration: none;
  font-size: 0.9rem;
  font-weight: 600;
}
